#include "../include/sleela_regex_natural.hpp"
#include <cctype>
#include <unordered_map>
namespace sleela::regex::natural { static const std::unordered_map<std::string_view,std::string> W{{"any","."},{"digit","[0-9]"},{"letter","[[:alpha:]]"},{"space","[[:space:]]"},{"one","="},{"optional","?"},{"some","+"},{"many","*"},{"begin","^"},{"end","$"},{"or","|"}}; std::string canonical_symbol(std::string_view w){auto i=W.find(w);return i==W.end()?std::string{}:i->second;} Status validate(std::string_view s,Diagnostic*d){if(s.empty()){if(d)*d={Status::null_source,0,"empty pattern"};return Status::null_source;}int depth=0;bool quote=false;for(size_t i=0;i<s.size();){char c=s[i];if(c=='"'){quote=!quote;++i;continue;}if(quote){++i;continue;}if(c=='('||c=='['||c=='<')++depth;else if(c==')'||c==']'||c=='>'){if(!depth){if(d)*d={Status::unbalanced,i,"unbalanced closing delimiter"};return Status::unbalanced;}--depth;}if(std::isalpha((unsigned char)c)){size_t j=i+1;while(j<s.size()&&std::isalpha((unsigned char)s[j]))++j;auto w=s.substr(i,j-i);if(W.find(w)==W.end()){if(d)*d={Status::unknown_word,i,"unknown Natural Form word"};return Status::unknown_word;}i=j;continue;}++i;}if(quote||depth){if(d)*d={Status::unbalanced,s.size(),"unbalanced delimiter or quote"};return Status::unbalanced;}if(d)*d={Status::ok,0,{}};return Status::ok;} }
